mapper.select:
select id, source, cve_id, title, vuln_type, severity, vendor_project, product, ecosystem, is_poisoning, aliases, description, reference_url, published_at, updated_at, created_at from vuln_intel
AND vuln_type = #{vulnType}
AND severity = #{severity}
AND (cve_id like concat('%', #{keyword}, '%') OR title like concat('%', #{keyword}, '%') OR vendor_project like concat('%', #{keyword}, '%') OR product like concat('%', #{keyword}, '%'))
AND published_at >= #{startDate}
AND published_at <= concat(#{endDate}, ' 23:59:59')
order by published_at desc, id desc limit 200
